i = M["limit_inf"]["R1"]["sparc"]; k1 = max(abs(i[TG[0]]["rms"] - 0.054087447879939264), abs(i[TG[0]]["U"] - 0.52)); k1a = M["alt_law_limit"][TG[0]]; k1b = max(abs(k1a["rms"] - 0.05371798965550355), abs(k1a["U"] - 0.44))
